import yaml


class ValuesHandling(object):

    def merge_values_file(self, src_file, dst_file):
        """
        :param src_file: values.yml or values_overriden.yml which have real values need to be merge to dst_file
        :param dst_file: values.yml or values_overriden.yml which value will be changed if src_file have this value,
                after merged, this file will be updated
        :return: None
        """
        common_dict = self._get_common_parameters(src_file, dst_file)
        with open(dst_file, "r") as f:
            dst_dict = yaml.load(f)
        self._merge_values(common_dict, dst_dict)
        with open(dst_file, "w") as f:
            yaml.dump(dst_dict, f)

    def _merge_values(self, src_dict, dst_dict):
        for key in src_dict:
            if isinstance(dst_dict[key], dict):
                self._merge_values(src_dict[key], dst_dict[key])
            else:
                dst_dict[key] = src_dict[key]

    def _get_common_parameters_from_two_dict(self, src_value, dst_value, common_value):
        if not isinstance(src_value, dict) or not isinstance(dst_value, dict):
            return src_value
        for src_key in src_value:
            if src_key in dst_value:
                common_value[src_key] = {}
                common_value[src_key] = self._get_common_parameters_from_two_dict(
                    src_value[src_key], dst_value[src_key], common_value[src_key])
        return common_value

    def _get_common_parameters(self, src_file, dst_file):
        with open(src_file, "r") as f_src:
            with open(dst_file, "r") as f_dst:
                src_file_dict = yaml.load(f_src)
                dst_file_dict = yaml.load(f_dst)
                common_value = {}
                self._get_common_parameters_from_two_dict(src_file_dict, dst_file_dict, common_value)
                return common_value
